#!/usr/bin/env bash set -e PROJECT\_DIR="$(pwd)" # Auto-detect and fix GUT folder naming if missing if [ ! -f "addons/gut/gut\_cmdln.gd" ]; then if [ -d "addons/Gut-9.3.0" ]; then echo "[\*] Fixing directory structure: Renaming addons/Gut-9.3.0 -&gt; addons/gut" mv addons/Gut-9.3.0 addons/gut elif [ -d "addons/gut-main" ]; then echo "[\*] Fixing directory structure: Renaming addons/gut-main -&gt; addons/gut" mv addons/gut-main addons/gut else echo "[\*] GUT addon missing. Downloading GUT v9.3.0 into addons/gut..." mkdir -p addons curl -sL https://github.com/bitwes/Gut/archive/refs/tags/v9.3.0.tar.gz | tar -xz -C addons/ mv addons/Gut-9.3.0 addons/gut fi fi TEST\_TARGET="${1:-res://test\_eas03\_shader\_bindings.gd}" echo "[\*] Executing Godot 4 GUT Test Suite ($TEST\_TARGET)..." godot --path "$PROJECT\_DIR" --headless -s res://addons/gut/gut\_cmdln.gd -gdir=res:// -gtest="$TEST\_TARGET" -gexit
